const u = $json.body || {};
if (u.callback_query) {
  const cq = u.callback_query;
  const [a, id] = String(cq.data || '').split(':');
  const map = { st_pub: 'publish', st_redo: 'redo', st_skip: 'skip' };
  if (!map[a]) return [];
  return [{ json: { job: map[a], storyId: id, feedback: '', callbackId: cq.id,
    chatId: String(cq.message && cq.message.chat && cq.message.chat.id) } }];
}
const m = u.message;
if (m && m.reply_to_message && m.text) {
  const t = String(m.reply_to_message.caption || m.reply_to_message.text || '');
  const f = t.match(/Story: (S[A-Z0-9]+)/);
  if (!f) return [];
  return [{ json: { job: 'redo', storyId: f[1], feedback: m.text, callbackId: '', chatId: String(m.chat.id) } }];
}
return [];

// ===== SETTINGS for the content agent =====
return [{ json: {
  CLAUDE_MODEL: 'claude-sonnet-5-5',
  TELEGRAM_BOT_TOKEN: '__TG_TOKEN__',
  TELEGRAM_CHAT_ID: '1683074207',
  // One key per Facebook Page (Page ID -> key)
  PAGE_TOKENS: {
    '480251769037941': '__PAGE_BBZ__',
    '121995197538415': '__PAGE_AUDIN__'
  },
  // Approved stories are posted at this hour (Algiers time). Approve after it = posted right away.
  PUBLISH_HOUR: 12,
  RENDER_URL: 'https://sultan-stories.vercel.app/api/story',
  RENDER_KEY: 'sultan7Kq2',
  // Google Drive content folder of each branch (month folders inside, each with a "Stories" folder of finished videos)
  DRIVE_ROOTS: {
    'Bab Ezzouar': '1yXYxcBocNz-DlTG2eMUs0eoJWX8-6emi'
  },
  // The same Drive video is not reposted before this many days
  VIDEO_REPEAT_DAYS: 30
}}];

// The content agent's "brain": decides what to do for this run.
const s = $('Settings').first().json;
const H = this.helpers;
const v = (x) => String(x == null ? '' : x).trim();
const rows = (n) => { try { return $(n).all().map((i) => i.json).filter((r) => Object.keys(r).length > 0); } catch (e) { return []; } };
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };

let job = {};
for (const n of ['Job: daily', 'Job: noon', 'Job: Telegram']) if (ran(n)) { job = $(n).first().json; break; }

const tg = (method, body) => H.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + s.TELEGRAM_BOT_TOKEN + '/' + method, body, json: true }).catch((e) => ({ error: e.message }));
const say = (text) => tg('sendMessage', { chat_id: s.TELEGRAM_CHAT_ID, text });
const G = 'https://graph.facebook.com/v21.0/';
const gerr = (e) => {
  const r = e.response || {};
  const b = r.body || r.data || (e.cause && e.cause.response && e.cause.response.data) || null;
  const msg = b && b.error ? (b.error.error_user_msg || b.error.message) : '';
  return msg || e.description || e.message || String(e);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Algiers time (UTC+1, no daylight saving)
const now = new Date(Date.now() + 3600 * 1000);
const today = now.toISOString().slice(0, 10);
const hour = now.getUTCHours();
const DAYS = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const stamp = now.toISOString().replace('T', ' ').slice(0, 16);

const branches = rows('Read Branches');
const menu = rows('Read Menu');
const offers = rows('Read Offers');
const photos = rows('Read Photos');
const stories = rows('Read Stories');
const findBranch = (name) => branches.find((b) => v(b['Branch']).toLowerCase() === v(name).toLowerCase());
const IGCOL = 'Instagram account ID (filled automatically)';
const parseD = (r) => { try { return JSON.parse(v(r['Design (JSON)'])); } catch (e) { return {}; } };
const driveVideos = (() => { try { const f = $('Drive: story videos').first().json.files; return Array.isArray(f) ? f : []; } catch (e) { return []; } })();
const driveBranch = v(Object.keys(s.DRIVE_ROOTS || {})[0]).toLowerCase();

const out = [];
const upd = (r) => out.push({ json: { kind: 'update', row: r } });

async function igIdFor(b) {
  if (v(b[IGCOL])) return v(b[IGCOL]);
  const pageId = v(b['Facebook Page ID']);
  const r = await H.httpRequest({ url: G + pageId + '?fields=instagram_business_account&access_token=' + encodeURIComponent(s.PAGE_TOKENS[pageId] || ''), json: true });
  if (!r.instagram_business_account) throw new Error('No Instagram account is linked to this Facebook Page');
  return r.instagram_business_account.id;
}

async function publish(row) {
  const b = findBranch(row['Branch']) || {};
  const pageId = v(b['Facebook Page ID']);
  const tok = s.PAGE_TOKENS[pageId] || '';
  const img = v(row['Image link']);
  const res = { ig: '', fb: '', errors: [] };
  const isVideo = parseD(row).type === 'video';
  try {
    const ig = await igIdFor(b);
    const body = isVideo ? { access_token: tok, video_url: img, media_type: 'STORIES' } : { access_token: tok, image_url: img, media_type: 'STORIES' };
    const c = await H.httpRequest({ method: 'POST', url: G + ig + '/media', body, json: true });
    let ready = false;
    for (let k = 0; k < (isVideo ? 40 : 15); k++) {
      const st = await H.httpRequest({ url: G + c.id + '?fields=status_code,status&access_token=' + encodeURIComponent(tok), json: true });
      if (st.status_code === 'FINISHED') { ready = true; break; }
      if (st.status_code === 'ERROR') throw new Error('Instagram could not read the ' + (isVideo ? 'video' : 'image') + (st.status ? ' (' + st.status + ')' : ''));
      await sleep(isVideo ? 5000 : 2000);
    }
    if (!ready && isVideo) throw new Error('Instagram took too long to process the video');
    const p = await H.httpRequest({ method: 'POST', url: G + ig + '/media_publish', body: { access_token: tok, creation_id: c.id }, json: true });
    res.ig = p.id;
  } catch (e) { res.errors.push('Instagram: ' + gerr(e)); }
  try {
    if (isVideo) {
      const st = await H.httpRequest({ method: 'POST', url: G + pageId + '/video_stories', body: { access_token: tok, upload_phase: 'start' }, json: true });
      await H.httpRequest({ method: 'POST', url: st.upload_url, headers: { Authorization: 'OAuth ' + tok, file_url: img }, json: true });
      const fin = await H.httpRequest({ method: 'POST', url: G + pageId + '/video_stories', body: { access_token: tok, video_id: st.video_id, upload_phase: 'finish' }, json: true });
      res.fb = v(fin.post_id || st.video_id || 'ok');
    } else {
      const ph = await H.httpRequest({ method: 'POST', url: G + pageId + '/photos', body: { access_token: tok, url: img, published: false }, json: true });
      const st = await H.httpRequest({ method: 'POST', url: G + pageId + '/photo_stories', body: { access_token: tok, photo_id: ph.id }, json: true });
      res.fb = v(st.post_id || st.id || 'ok');
    }
  } catch (e) { res.errors.push('Facebook: ' + gerr(e)); }
  return res;
}

async function publishAndReport(row) {
  const r = await publish(row);
  const okAny = r.ig || r.fb;
  upd({ 'Story ID': row['Story ID'], 'Status': okAny ? 'Published' : 'Publish failed', 'Instagram story ID': r.ig, 'Facebook story ID': r.fb });
  let msg = okAny ? '📲 Story ' + row['Story ID'] + ' (' + row['Branch'] + ') is live:' : '⚠️ Story ' + row['Story ID'] + ' could not be posted.';
  msg += '\nInstagram: ' + (r.ig ? '✅' : '❌') + '   Facebook: ' + (r.fb ? '✅' : '❌');
  if (r.errors.length) msg += '\n\nProblem:\n' + r.errors.join('\n');
  await say(msg);
}

function pickVideos(name, extra) {
  if (v(name).toLowerCase() !== driveBranch) return [];
  const lastUse = {}; const busy = new Set();
  for (const r of stories) {
    if (v(r['Branch']).toLowerCase() !== v(name).toLowerCase()) continue;
    const d = parseD(r); if (d.type !== 'video' || !d.driveId) continue;
    const st = v(r['Status']); const day = v(r['Date']).slice(0, 10);
    if (st === 'Published' && (!lastUse[d.driveId] || lastUse[d.driveId] < day)) lastUse[d.driveId] = day;
    if (['Waiting for Bill', 'Approved'].includes(st)) busy.add(d.driveId);
  }
  if (extra && extra.prevDrive) busy.add(extra.prevDrive);
  const limit = new Date(now.getTime() - Number(s.VIDEO_REPEAT_DAYS || 30) * 86400000).toISOString().slice(0, 10);
  const dur = (f) => Number((f.videoMediaMetadata && f.videoMediaMetadata.durationMillis) || 0);
  const ok = driveVideos.filter((f) => !busy.has(f.id) && (!lastUse[f.id] || lastUse[f.id] < limit) &&
    (!dur(f) || (dur(f) >= 3000 && dur(f) <= 60000)) && Number(f.size || 0) < 100e6);
  const fresh = ok.filter((f) => !lastUse[f.id]);
  for (let i = fresh.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [fresh[i], fresh[j]] = [fresh[j], fresh[i]]; }
  const old = ok.filter((f) => lastUse[f.id]).sort((a, b) => (lastUse[a.id] < lastUse[b.id] ? -1 : 1));
  return fresh.concat(old).slice(0, 10).map((f, i) => ({
    key: 'V' + (i + 1), id: f.id, name: v(f.name), sec: Math.round(dur(f) / 1000),
    thumb: f.thumbnailLink ? String(f.thumbnailLink).replace(/=s\d+$/, '=s400') : '', posted: lastUse[f.id] || ''
  }));
}

async function makeBrief(b, extra) {
  const name = v(b['Branch']);
  const mine = (r) => { const x = v(r['Branch']).toLowerCase(); return x === name.toLowerCase() || x === 'all'; };
  const menuTxt = menu.filter(mine).filter((r) => v(r['Available']).toLowerCase() !== 'no').map((r) =>
    '- ' + v(r['Category']) + ' | ' + v(r['Item']) + (v(r['Size']) ? ' (' + v(r['Size']) + ')' : '') + ': ' + v(r['Price (DA)']) + ' DA' +
    (v(r['Description']) ? ' | ' + v(r['Description']) : '')).join('\n');
  const offTxt = offers.filter(mine).filter((r) => {
    const st = v(r['Start date']), en = v(r['End date']);
    return (!st || st <= today) && (!en || en >= today);
  }).map((r) => '- ' + v(r['Offer']) + ': ' + v(r['Details'])).join('\n') || 'No active offer.';
  const ph = photos.filter((p) => v(p['Branch']).toLowerCase() === name.toLowerCase() && v(p['Active (yes/no)']).toLowerCase() !== 'no');
  const photoTxt = ph.map((p) => '- ' + v(p['Photo']) + ': ' + v(p['What it shows']) + (v(p['Notes for the agent']) ? ' (' + v(p['Notes for the agent']) + ')' : '')).join('\n');
  const past = stories.filter((r) => v(r['Branch']).toLowerCase() === name.toLowerCase()).slice(-15);
  const pastTxt = past.map((r) => {
    let d = {}; try { d = JSON.parse(v(r['Design (JSON)'])); } catch (e) {}
    const what = d.type === 'video' ? 'READY VIDEO: ' + v(d.name) : 'DESIGNED | title: ' + v(d.title).replace(/\n/g, ' ') + ' | photo: ' + v(d.photo);
    return '- ' + v(r['Date']).slice(0, 10) + ' | ' + v(r['Status']) + ' | ' + what +
      ' | idea: ' + v(r['Idea (why this story)']) + (v(r['Reach']) ? ' | reach: ' + v(r['Reach']) + ', replies: ' + v(r['Replies']) : '') +
      (v(r['Bill feedback']) ? ' | BILL FEEDBACK: ' + v(r['Bill feedback']) : '');
  }).join('\n') || 'No stories yet.';
  const lessons = past.map((r) => v(r['Lesson learned'])).filter(Boolean).slice(-5).map((l) => '- ' + l).join('\n') || 'None yet.';

  const system = `You are the content agent of Sultan ${name}, a fast-food restaurant in Algiers (Algeria). Every day you create ONE story for this branch's Instagram and Facebook. Bill, the owner, approves it on Telegram before it goes live.

## Your job
Decide the best story for today, then write it. Think like a good community manager: what will make people in ${name} hungry and make them call to order today?

## Two kinds of story
1. A READY VIDEO from the branch's Google Drive: a finished story video made by the team, posted exactly as it is. You see one preview image of each video.
2. A DESIGNED story: a food photo with text, made from the design fields below.
Mix both kinds over the week. Ready videos are real filmed content: use them most days. Use a designed story when you need to show a price, the current offer, opening hours, delivery zones or a poll, or when no video fits. Do not post the same kind more than 3 days in a row. Choose a video by what you see in its preview, and avoid a video that looks like one posted in the last days.

## Hard rules
- Text on the story is in French: short, punchy, friendly. No Arabic, no English on the story.
- Use ONLY this branch's menu, prices, offers, hours and delivery zones below. Never invent a dish, a price, an offer, a discount or a delivery promise.
- Use ONLY a photo from the photo list, with its exact "photo" value. The photo must show the dish you talk about (or be a neutral food photo for info stories like hours or delivery).
- Never mention another Sultan branch.
- No emoji in the story text (they cannot be printed).

## Variety and timing
- Do not repeat the same dish or the same angle as the last 3 stories. Rotate angles: dish + price, current offer, poll or question, delivery zones, opening hours, "plats complets", call to order, weekend, weather or season, special day.
- Use today's context: day of the week (weekend in Algeria is Friday and Saturday; on Friday the branch opens at 17:00), season and weather, Ramadan, Aïd, national holidays, school holidays, big football matches of Algeria if you know them.

## Learn
- Look at past stories: reach and replies show what works. Do more of what got the best results, less of what got weak results.
- Bill's feedback is the most important signal. Always follow it.

## Design fields (all text in French)
- photo: exact photo value from the list
- zoom: 1 to 2.2 (1 = whole photo, higher = closer crop). fx and fy: 0 to 1, where to center the crop (0.5 = center)
- kicker: small line above the title, max 28 characters (optional)
- title: big title, max 2 lines, max 14 characters per line, use \\n between lines
- text: one short sentence, max 45 characters (optional)
- chips: 0 to 4 short tags, max 16 characters each (optional)
- price: a number from the menu, without "DA" (optional). price_prefix: "dès" when it is a starting price (optional)
- sub: small line under, max 40 characters (optional)
- sticker_big + sticker_small: orange round sticker, ONLY for an offer (e.g. "OFFERTE" / "Margherita")
- footer: true shows the phone and "Livraison dispo" at the bottom. Use false only for polls.
Keep it light: never use all fields at once. 3 or 4 elements under the title are enough.

## Output
Reply with JSON only, nothing else:
{
  "idea": "1 or 2 sentences in English for Bill: what this story is and why today",
  "lesson": "1 short sentence in English: what you learned from past results and feedback (or 'Not enough results yet.')",
  "type": "video" or "design",
  "video": "V1 (only when type is video: the key of the chosen video)",
  "design": { "photo": "...", "zoom": 1, "fx": 0.5, "fy": 0.5, "kicker": "...", "title": "...", "text": "...", "chips": [], "price": "", "price_prefix": "", "sub": "", "footer": true }
}
When type is "video", leave design out. When type is "design", leave video out.`;

  let user = `Today: ${DAYS[now.getUTCDay()]} ${today} (Algiers).

### Branch
Branch: ${name}
Phone for orders: ${v(b['Phone for orders'])}
Opening hours: ${v(b['Opening hours'])}
Delivery zones: ${v(b['Delivery zones'])}
Notes: ${v(b['Notes'])}

### Menu
${menuTxt}

### Active offers
${offTxt}

### Photos you can use
${photoTxt}

### Past stories (oldest first)
${pastTxt}

### Your past lessons
${lessons}
`;
  const vids = pickVideos(name, extra);
  user += vids.length
    ? '\n### Ready videos from Drive (preview images follow, in the same order)\n' + vids.map((x) => x.key + ': ' + x.name + (x.sec ? ', ' + x.sec + ' s' : '') + (x.posted ? ', last posted ' + x.posted : ', never posted by you')).join('\n') + '\n'
    : '\n### Ready videos from Drive\nNo ready video available today: make a designed story.\n';
  if (extra && extra.redoOf) {
    user += `\n### Bill asked for a new version
Previous story: ${extra.prevDesign}
Bill's request: ${extra.feedback || 'Make a different story.'}
Make a new story that follows Bill's request.`;
  } else {
    user += '\nCreate today\'s story.';
  }
  const content = [{ type: 'text', text: user }];
  for (const x of vids) {
    if (!x.thumb) continue;
    try {
      const buf = Buffer.from(await H.httpRequest({ url: x.thumb, encoding: 'arraybuffer', timeout: 20000 }));
      const mt = buf[0] === 0x89 ? 'image/png' : 'image/jpeg';
      content.push({ type: 'text', text: 'Preview of ' + x.key + ' (' + x.name + '):' });
      content.push({ type: 'image', source: { type: 'base64', media_type: mt, data: buf.toString('base64') } });
    } catch (e) {}
  }
  const phone = v(b['Phone for orders']).replace(/\D/g, '');
  return {
    kind: 'claude', branch: name, isRedo: !!(extra && extra.redoOf),
    branchLabel: name.toUpperCase(),
    phone: phone.length === 10 ? phone.replace(/(\d{4})(\d{2})(\d{2})(\d{2})/, '$1 $2 $3 $4') : v(b['Phone for orders']),
    photoIds: ph.map((p) => v(p['Photo'])),
    videos: vids,
    system, userContent: content
  };
}

async function updateStats(b) {
  const name = v(b['Branch']);
  const tok = s.PAGE_TOKENS[v(b['Facebook Page ID'])] || '';
  for (const r of stories) {
    if (v(r['Branch']).toLowerCase() !== name.toLowerCase() || v(r['Status']) !== 'Published') continue;
    if (!v(r['Instagram story ID']) || v(r['Reach'])) continue;
    try {
      const ins = await H.httpRequest({ url: G + v(r['Instagram story ID']) + '/insights?metric=reach,replies&access_token=' + encodeURIComponent(tok), json: true });
      const get = (m) => { const x = (ins.data || []).find((d) => d.name === m); if (!x) return ''; return x.values && x.values[0] ? x.values[0].value : (x.total_value ? x.total_value.value : ''); };
      r['Reach'] = v(get('reach')); r['Replies'] = v(get('replies'));
      upd({ 'Story ID': r['Story ID'], 'Reach': r['Reach'], 'Replies': r['Replies'] });
    } catch (e) {
      if (v(r['Date']).slice(0, 10) < today) { r['Reach'] = 'n/a'; upd({ 'Story ID': r['Story ID'], 'Reach': 'n/a' }); }
    }
  }
}

// ===================== Jobs =====================
if (job.job === 'new') {
  const daily = branches.filter((b) => v(b['Daily story (yes/no)']).toLowerCase() === 'yes' && v(b['Facebook Page ID']));
  for (const b of daily) {
    await updateStats(b);
    const exists = stories.some((r) => v(r['Branch']).toLowerCase() === v(b['Branch']).toLowerCase() && v(r['Date']).slice(0, 10) === today &&
      ['Waiting for Bill', 'Approved', 'Published'].includes(v(r['Status'])));
    if (exists) continue;
    out.push({ json: await makeBrief(b) });
  }
}

if (job.job === 'publish_due') {
  for (const r of stories.filter((x) => v(x['Status']) === 'Approved')) await publishAndReport(r);
}

if (['publish', 'skip', 'redo'].includes(job.job)) {
  if (String(job.chatId) !== String(s.TELEGRAM_CHAT_ID)) return [];
  if (job.callbackId) await tg('answerCallbackQuery', { callback_query_id: job.callbackId });
  const row = stories.find((r) => v(r['Story ID']) === job.storyId);
  if (!row) { await say('⚠️ Story ' + job.storyId + ' not found in the sheet.'); return out; }
  const st = v(row['Status']);
  const final = ['Published', 'Skipped', 'Redone'];
  if (final.includes(st) && job.job !== 'redo') { await say('ℹ️ Story ' + job.storyId + ' was already handled (' + st + ').'); return out; }
  if (st === 'Redone') { await say('ℹ️ A new version of story ' + job.storyId + ' was already made. Use the newest one.'); return out; }
  if (v(row['Telegram message ID'])) await tg('editMessageReplyMarkup', { chat_id: s.TELEGRAM_CHAT_ID, message_id: Number(row['Telegram message ID']), reply_markup: { inline_keyboard: [] } });

  if (job.job === 'skip') {
    upd({ 'Story ID': row['Story ID'], 'Status': 'Skipped' });
    await say('⏭ Skipped. No story today for ' + row['Branch'] + '.');
  }
  if (job.job === 'publish') {
    if (hour < Number(s.PUBLISH_HOUR)) {
      upd({ 'Story ID': row['Story ID'], 'Status': 'Approved' });
      await say('✅ Approved. It will be posted at ' + s.PUBLISH_HOUR + ':00.');
    } else {
      await publishAndReport(row);
    }
  }
  if (job.job === 'redo') {
    const b = findBranch(row['Branch']);
    if (!b) { await say('⚠️ Branch ' + row['Branch'] + ' not found.'); return out; }
    if (st !== 'Published') upd({ 'Story ID': row['Story ID'], 'Status': 'Redone', 'Bill feedback': job.feedback || 'Redo' });
    else upd({ 'Story ID': row['Story ID'], 'Bill feedback': job.feedback || 'Redo' });
    await say('🔄 OK, making a new version…');
    out.push({ json: await makeBrief(b, { redoOf: row['Story ID'], prevDesign: v(row['Design (JSON)']), prevDrive: parseD(row).driveId, feedback: job.feedback }) });
  }
}

return out;

// Turns Claude's answer into a story (ready Drive video or designed image), sends it to Bill on Telegram, and logs it.
const s = $('Settings').first().json;
const H = this.helpers;
const v = (x) => String(x == null ? '' : x).trim();
const tg = (method, body) => H.httpRequest({ method: 'POST', url: 'https://api.telegram.org/bot' + s.TELEGRAM_BOT_TOKEN + '/' + method, body, json: true });
const say = (text) => tg('sendMessage', { chat_id: s.TELEGRAM_CHAT_ID, text }).catch(() => null);
const briefs = $('Needs Claude?').all(0).map((i) => i.json);
const now = new Date(Date.now() + 3600 * 1000);
const stamp = now.toISOString().replace('T', ' ').slice(0, 16);
const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const it = items[i].json;
  const b = briefs[i] || {};
  let r = null, err = '';
  if (it.error) err = 'Claude did not answer: ' + JSON.stringify(it.error).slice(0, 300);
  else {
    const raw = (it.content || []).map((c) => c.text || '').join('');
    try { r = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { err = 'Could not read the AI answer: ' + raw.slice(0, 200); }
  }
  let vid = null;
  if (r && r.type === 'video') vid = (b.videos || []).find((x) => x.key === v(r.video) || x.id === v(r.video)) || null;
  if (!r || (!vid && !r.design)) { await say('⚠️ The content agent failed for ' + b.branch + '.\n' + (err || 'No usable story in the AI answer.')); continue; }

  const id = 'S' + now.toISOString().slice(2, 10).replace(/-/g, '') + Math.random().toString(36).slice(2, 5).toUpperCase();
  const keyboard = { inline_keyboard: [[{ text: '✅ Publish', callback_data: 'st_pub:' + id }, { text: '🔄 Redo', callback_data: 'st_redo:' + id }], [{ text: '⏭ Skip', callback_data: 'st_skip:' + id }]] };
  let d, url, msgId = '', status = 'Waiting for Bill';
  const head = (b.isRedo ? '🔄 New version' : '🆕 Today\'s story') + ' – ' + b.branch;
  const tail = '\n\n💡 ' + v(r.idea) + (v(r.lesson) ? '\n\n📈 ' + v(r.lesson) : '') + '\n\n✍️ Reply to this message to ask for a change.\nStory: ' + id;

  if (vid) {
    d = { type: 'video', driveId: vid.id, name: vid.name };
    url = 'https://drive.usercontent.google.com/download?id=' + vid.id + '&export=download&confirm=t';
    const caption = head + '\n🎬 Ready video from Drive: ' + vid.name + tail;
    try {
      const m = await tg('sendVideo', { chat_id: s.TELEGRAM_CHAT_ID, video: url, caption: caption.slice(0, 1000), supports_streaming: true, reply_markup: keyboard });
      msgId = String(m.result.message_id);
    } catch (e) {
      try {
        const m = await tg('sendPhoto', { chat_id: s.TELEGRAM_CHAT_ID, photo: vid.thumb, caption: (caption + '\n▶️ Watch: https://drive.google.com/file/d/' + vid.id + '/view').slice(0, 1000), reply_markup: keyboard });
        msgId = String(m.result.message_id);
      } catch (e2) {
        status = 'Telegram failed';
        await say('⚠️ Could not send the story to Telegram. Video: https://drive.google.com/file/d/' + vid.id + '/view\nStory: ' + id);
      }
    }
  } else {
    d = r.design;
    if (!(b.photoIds || []).includes(d.photo)) d.photo = (b.photoIds || [])[0];
    d.branch_label = b.branchLabel;
    d.phone = b.phone;
    url = s.RENDER_URL + '?k=' + s.RENDER_KEY + '&d=' + Buffer.from(JSON.stringify(d), 'utf8').toString('base64url');
    let renderErr = '';
    try { await H.httpRequest({ url, encoding: 'arraybuffer', timeout: 60000 }); } catch (e) { renderErr = e.message; }
    if (renderErr) {
      status = 'Image failed';
      await say('⚠️ The story image could not be made (' + renderErr + ').\nStory: ' + id);
    } else {
      try {
        const m = await tg('sendPhoto', { chat_id: s.TELEGRAM_CHAT_ID, photo: url, caption: (head + '\n🎨 Designed story' + tail).slice(0, 1000), reply_markup: keyboard });
        msgId = String(m.result.message_id);
      } catch (e) {
        status = 'Telegram failed';
        await say('⚠️ Could not send the story photo to Telegram. Image: ' + url + '\nStory: ' + id);
      }
    }
  }
  out.push({ json: {
    'Story ID': id, 'Date': stamp, 'Branch': b.branch, 'Status': status,
    'Idea (why this story)': v(r.idea), 'Design (JSON)': JSON.stringify(d), 'Image link': url,
    'Telegram message ID': msgId, 'Instagram story ID': '', 'Facebook story ID': '',
    'Reach': '', 'Replies': '', 'Bill feedback': '', 'Lesson learned': v(r.lesson)
  } });
}
return out;
